import * as THREE from 'three/webgpu';
import { texture as nodeTexture } from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const {
    position = [-3.2, -0.3, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
    assets = {}
  } = config;

  // Load texture (synchronous via cache)
  const imgUrl = assets.imageUrl;
  const tex = ctx.textureLoader(imgUrl);
  const texNode = nodeTexture(tex);

  // Plane geometry respecting atlas aspect ratio (512:320)
  const aspect = 512 / 320; // 1.6
  const geometry = new THREE.PlaneGeometry(aspect, 1, 1, 1);

  // Basic material (no lighting required)
  const material = new THREE.MeshBasicNodeMaterial({
    map: texNode,
    // Ensure correct handling of premultiplied alpha if needed
    // (defaults are fine for a static composition)
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...position);
  mesh.rotation.set(...rotation);
  mesh.scale.set(...scale);

  // No cinematic primitives to apply for this node

  // Event handlers placeholder (none defined)
  mesh.userData.handlers = {};

  // Cleanup routine
  mesh.userData.cleanup = () => {
    // Dispose of geometry & material
    geometry.dispose();
    material.dispose();

    // If the texture is owned exclusively, dispose it.
    // ctx.textureLoader typically returns cached textures; dispose only if
    // you are certain it's not shared elsewhere.
    if (tex && tex.dispose) {
      tex.dispose();
    }

    // Kill any GSAP timelines that might have been created in the future
    gsap.killTweensOf(mesh);
  };

  return mesh;
}
